"""Magi: The Labyrinth of Magic skill lines (25): Djinn equips, vessels, Rukh, magoi, borg and the people of its world.
Every line is ONE recognisable power or role; numbers stay inside tools/lines/catalog.py.
"""
from lines_lib import Line, Stance, Stat, Art, Pas


def T(n, d, i, **p):
    return Stance(n, d, i, p)


def N(n, d, attr, amt, i, op="add"):
    return Stat(n, d, attr, amt, op, i)


def A(n, d, k, i, **p):
    return Art(n, d, k, p, i)


def P(n, d, k, i, **p):
    return Pas(n, d, k, p, i)


def line(id, name, desc, color, bg, icon, book, lore, st, sts, arts, pas, fin):
    return Line(id, name, "magi", desc, color, bg, icon, book, lore, st, sts, arts, pas, fin)


