    line("magnostadt_staff_wizard", "Magnostadt Staff Wizard",
         "A wizard of the great academy: you carry a staff, cast from a book of formulas and rely on training instead of talent. Fast casting, broad spellbook, steady hands.",
         "#5aa0e0", "tower", "minecraft:blaze_rod", "Magnostadt Formula Book", "Neat columns of spell formulas, graded in red ink by a stern examiner.",
         [T("Steady Casting", "Plant the staff and cast carefully: crits and a firm guard, a slow walk.", "minecraft:blaze_rod", crit_chance=.12, armor=2, speed_pct=-.08, vfx="MAGIC_CIRCLE"),
          T("Rapid Casting", "Quick fingers and a loose cloak: faster and harder-hitting, thin hide.", "minecraft:feather", speed_pct=.1, damage_pct=.2, armor=-3, vfx="WIND_RING")],
         [N("Student's Vigor", "Late nights in the library.", "max_health", 2, "minecraft:golden_carrot"),
          N("Staff Reach", "A staff's length of reach.", "entity_interaction_range", .5, "minecraft:stick"),
          N("Academy Robes", "Padded, enchanted robes.", "armor", 2, "minecraft:leather_chestplate"),
          N("Quick Caster", "Faster follow-up.", "attack_speed", .15, "minecraft:clock")],
         [A("Spell Volley", "Cast a quick rapid-fire volley of bolts at the foe you look at.", "barrage", "minecraft:blaze_rod", vfx="MAGIC_CIRCLE", damage=3, shots=6),
          A("Lightning Strand", "A bolt of lightning that jumps from foe to foe.", "chain_hit", "minecraft:lightning_rod", vfx="LIGHTNING_FIEND", damage=7, jumps=4),
          A("Fall of Stars", "Call a bright star down on the place you look at after a short delay.", "meteor_drop", "minecraft:nether_star", vfx="MAGIC_CIRCLE", damage=13),
          A("Burst Formula", "Fire a prepared formula: a ring of force blasts out around you.", "ring_burst", "minecraft:enchanted_book", vfx="MAGIC_CIRCLE", damage=6, radius=4),
          A("Wizard's Ward", "Chalk a ward in the air: a shield that soaks damage.", "shield", "minecraft:shield", vfx="MAGIC_CIRCLE", absorb_hearts=5),
          A("Piercing Bolt", "A single bolt along your sight line that pierces everything.", "ray_shot", "minecraft:end_rod", vfx="LIGHTNING_SPEAR", damage=9, pierce=2),
          A("Recovery Draught", "Down a prepared draught: heal and regenerate for a while.", "heal_self", "minecraft:potion", vfx="SPIRIT_AURA", amount=7)],
         [P("Diligent Study", "Kills give more experience.", "xp_bonus", "minecraft:experience_bottle", pct=.15),
          P("Formula Mastery", "Your spells may strike critically.", "crit", "minecraft:enchanted_book"),
          P("Anti-Spell Training", "Magic damage hardly hurts you.", "resist", "minecraft:amethyst_shard", damage_kind="magic", pct=.35),
          P("Quick Recovery", "Your wounds close over time.", "mending", "minecraft:honey_bottle"),
          P("Specimen Collection", "A kill may drop an extra stack of its loot.", "drop_bonus", "minecraft:chest"),
          P("Theory of Feeding", "A share of the damage you deal comes back as health.", "lifesteal", "minecraft:glistering_melon_slice"),
          P("Light Lessons", "You tire more slowly.", "hunger_saver", "minecraft:bread")],
         [A("Great Formula: Fall of the Stars", "The thesis of a lifetime: stars rain on the place you look at.", "meteor_drop", "minecraft:nether_star",
            vfx="MAGIC_CIRCLE", damage=36, radius=8, delay=24, cooldown=1300, cost=.06),
          A("Grand Thunder Array", "A thunderstorm in a formula: lightning leaps through a whole crowd of foes.", "chain_hit", "minecraft:lightning_rod",
            vfx="LIGHTNING_FIEND", damage=24, jumps=5, jump_range=9, cooldown=1200, cost=.05)]),

    line("solomon_wisdom_sage", "Solomon's Wisdom Sage",
         "An echo of the first king's gift: protective, patient and oddly cheerful. Wisdom turns into shields, shields into light and light into a blessing you hand to everyone nearby.",
         "#fff2a8", "stellar", "minecraft:enchanted_golden_apple", "Teachings of the First King", "Plain words about kindness, written in the margins of a very old map.",
         [T("Seat of Wisdom", "Sit in the center: a calm, protective stance with mending, little offense.", "minecraft:enchanted_book", armor=3, regen=.8, damage_pct=-.15, vfx="MAGIC_CIRCLE"),
          T("Gaze of Guidance", "Step forward to lead: faster and stronger, lightly armored.", "minecraft:golden_boots", speed_pct=.1, damage_pct=.15, armor=-2, vfx="SPIRIT_AURA")],
         [N("Ancient Vitality", "A long-lived soul.", "max_health", 4, "minecraft:enchanted_golden_apple"),
          N("Kind Strength", "Gentle but firm.", "attack_damage", 1, "minecraft:golden_sword"),
          N("Warded Robes", "The old weave.", "armor", 2, "minecraft:golden_chestplate")],
         [A("Gift of Courage", "Impart courage: you and the allies around you gain strength.", "buff_aura", "minecraft:golden_apple", effect="strength", vfx="SPIRIT_AURA", radius=10),
          A("Sage's Ward", "An old ward rises around you and soaks up a great deal of damage.", "shield", "minecraft:enchanted_book", vfx="MAGIC_CIRCLE", absorb_hearts=6, resist_amp=1),
          A("Descent of Light", "A column of gentle light falls on the place you look at after a short delay.", "meteor_drop", "minecraft:end_rod", vfx="SPIRIT_AURA", damage=13),
          A("Blessing of Warmth", "A warm light heals you and the allies around you.", "heal_pulse", "minecraft:glowstone_dust", vfx="SPIRIT_AURA", amount=7),
          A("Silencing Light", "A cone of calm light slows and softens the foes in front of you.", "debuff_cone", "minecraft:glowstone", effect="slowness", effect2="weakness", seconds2=4, vfx="SPIRIT_AURA"),
          A("Wise Step", "Take one measured step: a short teleport forward.", "blink", "minecraft:ender_eye", vfx="SPIRIT_AURA", distance=9),
          A("Peace Pulse", "A wave of calm stills the creatures around you for a moment.", "stun_ring", "minecraft:white_wool", vfx="MAGIC_CIRCLE", seconds=2)],
         [P("Unshaken by Sorcery", "Magic damage hardly hurts you.", "resist", "minecraft:enchanted_book", damage_kind="magic", pct=.4),
          P("Lantern of Wisdom", "Allies near you regenerate a little.", "aura", "minecraft:lantern", effect="regeneration", target="allies"),
          P("Eternal Student", "Kills give more experience.", "xp_bonus", "minecraft:experience_bottle"),
          P("Calm Heart", "You take less damage while at full health.", "reduce_when", "minecraft:white_wool", condition="full_health", pct=.15),
          P("Old Memory", "Your wounds close over time.", "mending", "minecraft:honey_bottle"),
          P("Warm Light", "During the day you slowly heal.", "regen_when", "minecraft:sunflower", condition="day", per_second=.7),
          P("Fate's Turn", "You may avoid a blow completely.", "dodge", "minecraft:feather", chance=.1)],
         [A("Great Bounty of the Sage", "Pour the first king's wisdom over everyone nearby: a long, mighty blessing of strength.", "buff_aura", "minecraft:nether_star",
            vfx="SPIRIT_AURA", effect="strength", amp=1, radius=12, seconds=16, cooldown=1400, cost=.06),
          A("Sage's Verdict", "A pure beam of light crosses the field and pierces everything on its line.", "ray_shot", "minecraft:beacon",
            vfx="LIGHTNING_SPEAR", damage=36, range=32, pierce=3, cooldown=1250, cost=.06)]),

    line("fanalis_brawler", "Fanalis Brawler",
         "A body built to leap higher, strike harder and outrun the magic aimed at it: no wand, no Djinn, just a ferocious physique. Kicks that crack stone and a grin while you do it.",
         "#c87f3a", "sand", "minecraft:leather_boots", "Warrior's Body Journal", "Scribbled by a trainer who clearly could not keep up with the subject.",
         [T("Roaring Muscle", "Full force: heavy blows and crits, light on armor.", "minecraft:iron_axe", damage_pct=.28, crit_chance=.08, armor=-3, vfx="WIND_SLASH"),
          T("Coiled Spring", "Wind up: faster and bouncier, steady feet.", "minecraft:rabbit_foot", speed_pct=.15, knockback_res=.3, damage_pct=-.05, vfx="WIND_RING")],
         [N("Monstrous Stamina", "A body that tires last.", "max_health", 6, "minecraft:cooked_beef"),
          N("Crushing Kick", "Legs like pistons.", "attack_damage", 2, "minecraft:iron_boots"),
          N("Spring in the Heel", "Leaps taller than a house.", "jump_strength", .1, "minecraft:rabbit_foot"),
          N("Sprinter's Frame", "A faster pace.", "movement_speed", .06, "minecraft:leather_boots", op="mult")],
         [A("Axe Kick Rise", "A looping kick that sends the foe in front of you flying upward.", "uppercut", "minecraft:iron_boots", vfx="WIND_SLASH", damage=9),
          A("Boulder Leap", "Jump a clear building's height and come down on the foes below.", "leap_slam", "minecraft:stone", vfx="EARTH_SPIKES", damage=10, height=1),
          A("Lightning Rush", "Cover the distance in a heartbeat and hit everything on the way.", "dash_strike", "minecraft:leather_boots", vfx="WIND_SLASH", damage=9, distance=10),
          A("Crescent Kick", "A high crescent kick through the cone in front of you.", "cone_strike", "minecraft:feather", vfx="WIND_SLASH", damage=8, half_angle=60),
          A("Hundred-Kick Spin", "Spin on the spot, kicking everything around you several times.", "whirlwind", "minecraft:iron_boots", vfx="WIND_TORNADO", damage=3, hits=5),
          A("Muscle Surge", "Flex until the sweat flies: strength and speed for a while.", "buff_self", "minecraft:cooked_beef", effect="strength", effect2="speed", vfx="SPIRIT_AURA"),
          A("Stomp Line", "Stamp and send a crack along the ground ahead of you.", "ground_wave", "minecraft:cobblestone", vfx="STONE_SPIKES", damage=8)],
         [P("Born Sprinter", "You hit harder while sprinting.", "sprint_bonus", "minecraft:sugar", bonus=.25),
          P("Momentum of the Chase", "Blows in a row grow stronger until you stop fighting.", "momentum", "minecraft:blaze_rod"),
          P("Instinct", "You may avoid a blow completely.", "dodge", "minecraft:leather_boots", chance=.12),
          P("Cat Landing", "You take much less fall damage.", "fall_guard", "minecraft:slime_ball", pct=.6),
          P("Kick Rhythm", "Every few blows in a row hit much harder.", "combo", "minecraft:clock", hits=3),
          P("Heavy Kicks", "Your blows may shove the foe back.", "knockback_on_hit", "minecraft:piston", strength=.6),
          P("Finishing Instinct", "You deal much more damage to nearly dead foes.", "execute_threshold", "minecraft:flint")],
         [A("Warrior's Wrath", "Leap to a great height and come down with every ounce of strength, cracking the ground.", "leap_slam", "minecraft:netherite_boots",
            vfx="EARTH_SPIKES", damage=34, radius=6, height=1.2, knockback=2, cooldown=1250, cost=.05),
          A("Rain of Kicks", "A blur of kicks in every direction: dozens of strikes in a few seconds.", "whirlwind", "minecraft:iron_boots",
            vfx="WIND_TORNADO", damage=8, hits=7, radius=5, cooldown=1200, cost=.05)]),

    line("legionary_phalanx_shield", "Legionary Phalanx Shield",
         "A drilled soldier of a shield-and-spear army: fight shoulder to shoulder, advance in step and be the reason the line holds. Discipline as a weapon.",
         "#b03a3a", "iron", "minecraft:shield", "Legion Drill Manual", "A manual of the formations in a clear, square hand; no flourishes.",
         [T("Shield Wall", "Plant your feet and lock shields: heavy guard, hard to move, slow.", "minecraft:shield", armor=6, knockback_res=.5, speed_pct=-.12, damage_pct=-.1, vfx="MIRROR_PANE"),
          T("Spear Advance", "Step forward in rank: stronger thrusts and a faster pace, shield lowered.", "minecraft:trident", damage_pct=.2, speed_pct=.08, armor=-2, vfx="WIND_SLASH")],
         [N("Veteran's Constitution", "Years of marching.", "max_health", 4, "minecraft:cooked_beef"),
          N("Legion Plate", "Standard-issue armor.", "armor", 3, "minecraft:iron_chestplate"),
          N("Spear Arm", "A straight, strong thrust.", "attack_damage", 1, "minecraft:iron_ingot"),
          N("Formation Footing", "Hard to move off the line.", "knockback_resistance", .1, "minecraft:anvil")],
         [A("Hold the Rank", "A shout that draws every hostile creature nearby onto your shield.", "taunt", "minecraft:goat_horn", vfx="MIRROR_PANE", targets=6),
          A("Spear Wall", "A rank of spears thrusts down the ground ahead of you.", "ground_wave", "minecraft:trident", vfx="WIND_SLASH", damage=8, length=11),
          A("Testudo", "Raise the shield overhead: a thick shield that soaks damage.", "shield", "minecraft:shield", vfx="MIRROR_PANE", absorb_hearts=6, resist_amp=1),
          A("Pilum Sweep", "A wide sweep of the spear through the cone in front of you.", "cone_strike", "minecraft:iron_sword", vfx="WIND_SLASH", damage=8, half_angle=50),
          A("Legion Rations", "Rations shared in the line: heal yourself and allies around you.", "heal_pulse", "minecraft:bread", vfx="SPIRIT_AURA", amount=6),
          A("Parry and Return", "For a few seconds a share of the damage you take is thrown back.", "ward_reflect", "minecraft:iron_bars", vfx="MIRROR_PANE"),
          A("Shield Slam", "Slam the shield into the ground: nearby creatures stagger and stop for a moment.", "stun_ring", "minecraft:anvil", vfx="STONE_SPIKES", seconds=2)],
         [P("Drilled Defence", "You take less damage while in a fight.", "reduce_when", "minecraft:iron_chestplate", condition="in_combat", pct=.12),
          P("Arrow Drill", "Projectile damage hardly hurts you.", "resist", "minecraft:arrow", damage_kind="projectile", pct=.4),
          P("Braced Shield", "Your blows may shove the foe back.", "knockback_on_hit", "minecraft:piston", strength=.5),
          P("Legion Standard", "Allies near you stand tougher.", "aura", "minecraft:red_banner", effect="resistance", target="allies"),
          P("Last Rank", "When you are nearly dead you are shielded for a few seconds.", "last_stand", "minecraft:totem_of_undying"),
          P("Field Surgeon", "Your wounds close over time.", "mending", "minecraft:honey_bottle"),
          P("Steady Thrust", "Every few blows in a row hit much harder.", "combo", "minecraft:clock", hits=4)],
         [A("Unbreakable Formation", "The whole line locks: a huge shield for you and a long time to enjoy it.", "shield", "minecraft:iron_block",
            vfx="MIRROR_PANE", absorb_hearts=12, resist_amp=1, seconds=12, cooldown=1400, cost=.06),
          A("Legion Charge", "The line moves: a spear thrust that tears across the field ahead.", "ground_wave", "minecraft:netherite_sword",
            vfx="WIND_SLASH", damage=26, length=18, width=4, knockback=1.5, cooldown=1200, cost=.05)]),

    line("fog_troupe_bandit", "Fog Troupe Bandit",
         "A thief with a cause: smoke bombs, rooftops and an eye for the one purse that matters. Strike fast, vanish faster and never keep what you steal for yourself.",
         "#6e6e7e", "city", "minecraft:gold_nugget", "Night-Rooftop Roster", "A list of rooftops, guard rotations and who owes whom a favor.",
         [T("Rooftop Run", "Light feet and a sharp eye: fast with better crits, no armor.", "minecraft:leather_boots", speed_pct=.18, crit_chance=.1, armor=-4, vfx="WIND_RING"),
          T("Alley Brawler", "Dirty fighting: harder hits and a firm stance, a bit slower.", "minecraft:iron_sword", damage_pct=.2, knockback_res=.3, speed_pct=-.05, vfx="WIND_SLASH")],
         [N("Street Constitution", "Built from bad meals and worse nights.", "max_health", 2, "minecraft:bread"),
          N("Light Fingers", "Quick hands.", "attack_speed", .15, "minecraft:feather"),
          N("Rooftop Spring", "A high jump for the next roof.", "jump_strength", .06, "minecraft:rabbit_foot"),
          N("Fence's Luck", "You always find something.", "luck", 2, "minecraft:gold_nugget")],
         [A("Grapple Hop", "Fire a hook and zip a short way forward.", "blink", "minecraft:fishing_rod", vfx="THREAD_LINE", distance=10),
          A("Snatch and Run", "Dash through a line of foes, cutting as you go.", "dash_strike", "minecraft:iron_sword", vfx="WIND_SLASH", damage=8),
          A("Smoke Bomb", "Drop a smoke bomb: creatures around you are blinded while you slip away.", "smoke", "minecraft:gunpowder", vfx="SHADOW_POOL", radius=6),
          A("Coin Flick Strike", "A fast stab that hits much harder the weaker the foe is.", "execute", "minecraft:iron_sword", vfx="WIND_SLASH", damage=9),
          A("Case the Mark", "Mark your target: it takes extra damage for a while.", "mark", "minecraft:spyglass", vfx="MAGIC_CIRCLE", range=22),
          A("Flash Powder", "A burst of flash powder freezes the creatures around you for a heartbeat.", "stun_ring", "minecraft:glowstone_dust", vfx="WIND_RING", seconds=2),
          A("Throwing Knives", "Hurl a fan of knives at the foe you look at.", "barrage", "minecraft:iron_nugget", vfx="WIND_SLASH", damage=3, shots=6)],
         [P("Pickpocket", "A kill may drop an extra stack of its loot.", "drop_bonus", "minecraft:gold_nugget", chance=.15),
          P("Slippery", "You may avoid a blow completely.", "dodge", "minecraft:leather_boots", chance=.12),
          P("Hidden in Plain Sight", "While you sneak you turn invisible.", "self_effect_when", "minecraft:glass", effect="invisibility", condition="sneaking"),
          P("Fence's Cut", "A kill heals you and speeds you up for a moment.", "kill_reward", "minecraft:gold_nugget", effect="speed", heal=2),
          P("Rooftop Roll", "You take much less fall damage.", "fall_guard", "minecraft:leather_boots", pct=.6),
          P("Crime Pays", "Your blows may strike critically.", "crit", "minecraft:iron_sword"),
          P("Dirty Finish", "You deal much more damage to nearly dead foes.", "execute_threshold", "minecraft:flint")],
         [A("Midnight Heist", "Every knife you own flies at the foe you look at.", "barrage", "minecraft:iron_sword",
            vfx="WIND_SLASH", damage=8, shots=8, range=22, cooldown=1200, cost=.05),
          A("Grand Escape", "A final mad dash through the enemy line, cutting a path as you go.", "dash_strike", "minecraft:ender_pearl",
            vfx="SHADOW_POOL", damage=28, distance=11, targets=6, cooldown=1250, cost=.05)]),

    line("multi_vessel_warlord", "Multi-Vessel Warlord",
         "A conqueror who wears several Djinn at once: flame, earth and thunder in one body. You fight like an army, and every war has a plan.",
         "#a02c2c", "blood", "minecraft:netherite_chestplate", "Warlord's Campaign Atlas", "Marching orders for a war of three fronts, written with a flourish.",
         [T("Triple Equip", "Full conquest: heavy blows and a steady guard, slow to move.", "minecraft:netherite_chestplate", damage_pct=.22, armor=4, speed_pct=-.07, vfx="FLAME_EXPLOSION"),
          T("Swift Campaign", "Shift between the Djinn quickly: fast and sharp, lighter plate.", "minecraft:netherite_boots", speed_pct=.12, crit_chance=.08, armor=-3, vfx="LIGHTNING_FIEND")],
         [N("Warlord's Constitution", "Command takes a body.", "max_health", 4, "minecraft:enchanted_golden_apple"),
          N("Conqueror's Strength", "Triple the arm.", "attack_damage", 2, "minecraft:netherite_sword"),
          N("Triple Plate", "Layers of Djinn armor.", "armor", 3, "minecraft:netherite_chestplate"),
          N("Command Poise", "Unmoved on the field.", "knockback_resistance", .15, "minecraft:netherite_ingot")],
         [A("Crimson Crescent", "A sweeping crescent of flame through the cone in front of you.", "cone_strike", "minecraft:netherite_sword", vfx="FIRE_SPIRAL", damage=9, half_angle=55),
          A("Fall of the Tower", "A burning stone tower crashes onto the place you look at after a short delay.", "meteor_drop", "minecraft:magma_block", vfx="FLAME_EXPLOSION", damage=14),
          A("Triple Burst", "Flame, stone and lightning burst out around you in one ring.", "ring_burst", "minecraft:nether_star", vfx="LIGHTNING_FIEND", damage=7, radius=4.5),
          A("War Cry", "Roar your campaign: you and the allies around you gain strength.", "buff_aura", "minecraft:red_banner", effect="strength", vfx="SPIRIT_AURA", radius=10),
          A("Cavalry Rush", "Drive through the line like a horse and rider, cutting everything in the way.", "dash_strike", "minecraft:saddle", vfx="WIND_SLASH", damage=9, distance=9),
          A("Thunder Link", "A lightning bolt jumps from foe to foe.", "chain_hit", "minecraft:lightning_rod", vfx="LIGHTNING_FIEND", damage=7, jumps=4),
          A("Djinn Surge", "Let the Djinn through: strength and resistance for a while.", "buff_self", "minecraft:blaze_powder", effect="strength", effect2="resistance", vfx="SPIRIT_AURA")],
         [P("Conqueror's Pride", "You deal more damage while at full health.", "dmg_when", "minecraft:gold_ingot", condition="full_health", bonus=.2),
          P("Drink of Victory", "A share of the damage you deal comes back as health.", "lifesteal", "minecraft:glistering_melon_slice"),
          P("Warlord's Banner", "Allies near you fight with more strength.", "aura", "minecraft:red_banner", effect="strength", target="allies"),
          P("Spoils of War", "A kill heals you and fills you with strength.", "kill_reward", "minecraft:bone", effect="strength", heal=3),
          P("Titan Hunter", "You deal more damage to boss-class creatures.", "dmg_vs", "minecraft:wither_skeleton_skull", category="boss", bonus=.25),
          P("Veteran's Eye", "Your blows may strike critically.", "crit", "minecraft:netherite_sword"),
          P("Camp Mending", "Your wounds close over time.", "mending", "minecraft:honey_bottle")],
         [A("Triple Extreme Magic", "Three Djinn answer at once: a vast wave of fire, rock and lightning along the ground.", "ground_wave", "minecraft:nether_star",
            vfx="FLAME_TRAIL", damage=30, length=20, width=4.5, knockback=1.5, cooldown=1300, cost=.06),
          A("Fall of the Empire", "The sky itself breaks: a fiery column crashes down on the place you look at.", "meteor_drop", "minecraft:fire_charge",
            vfx="FLAME_EXPLOSION", damage=38, radius=8, delay=26, cooldown=1300, cost=.06)]),
